INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homelab-server-room', 'The World Is Your Dashboard', 'The Server Room', 'One glowing panel per homelab node, pinned in your house or to housing furniture, with backlight and derez driven by live health checks.', 'Walk down an aisle of Tall Cabinets, each green with a btop or load readout. The NAS stops answering: its panel flickers amber, then red, and your pet swings toward it. Double-click flies you into an ssh session on that box. FC members holding a read-only key see the same wall when they walk in.', 'Health comes from a hidden capture session or agent probes (ping/tcp/http, node_exporter, incus list) via a new STATUS/EVENT frame, never from the panels, which sleep. Lua maps host to ok/warn/down and sets per-panel tint/backlight; move rez from global host.world_rez to per session in worldview.nelua. Placement uses house-id-aware anchors (see furniture-anchors). Drill-in reuses click focus, fly-in and per-host ssh profiles. Shared view uses read-only guest tokens (see over-the-shoulder-pets).', 'No depth test, so panels show through walls. A dozen live btop panels cost real FPS. Housing structs move between patches. Probe flaps cause alert fatigue; this is not a pager. Showing dashboards to an FC leaks hostnames and IPs.', 'homelab folks, sysadmins, SREs, sysadmin-heavy FCs', 1, 1, 0, 8, 'stretch', 'weeks', 0, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ops-weather', 'The World Is Your Dashboard', 'Ops Weather', 'Server health sets your local weather, client-side, so you feel an outage before you read about it.', 'All green: Fair Skies. Load climbs and clouds roll in. A failed CI run or degraded pool brings a thunderstorm, rain beads on your panels and a lightning pulse on the failing host''s backlight. Fix it and the sky clears.', 'Agent probe runner sends status over a new EVENT frame. New ops.lua maps states to per-territory weather ids with hysteresis. Shim adds SetWeatherOverride/ClearWeatherOverride beside GetEnvironment using the client-side WeatherManager path Brio and Weatherman use. M.lighting() already reads weather and rain, so tint and backlight follow for free; rain beads drawn in worldview.nelua.', 'Not every weather id is valid per territory; houses and duties have none or script their own. Hides real weather from fishers and gatherers, so it needs a toggle and guaranteed restore on unload, zone change and duty. Fights Brio or Weatherman.', 'sysadmins, homelab folks, SREs, streamers', 1, 1, 1, 8, 'stretch', 'days', 1, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('alertmanager-fates', 'The World Is Your Dashboard', 'Alertmanager FATEs', 'Prometheus alerts appear as FATE-style rings on the ground near you, with countdown, severity and a graded resolve.', 'While gathering, an orange ring pulses nearby: ''DiskPressure: nas/tank 91% (critical)''. Walk in and a panel rises running a read-only runbook (zpool status). When it resolves, the ring closes with a gold, silver or bronze grade by time to fix.', 'Capture session (ghostty.run) curls Alertmanager and Prometheus, flattened to TSV with jq. Lua keys alerts by fingerprint and anchors rings near the player. New Nelua primitive ghostty.draw_ring projects a tinted polyline. Walk-in by distance to ghostty.player(); rings hidden while BoundByDuty or InCombat.', 'No depth, rings float or sink on slopes without a BGCollision raycast forward. Walk-in must never auto-remediate: read-only or confirm. Cap alert floods; keep Alertmanager tokens out of lua/init.lua.', 'homelab folks, on-call SREs, sysadmins who raid', 1, 1, 0, 8, 'stretch', 'days', 2, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homelab-minion-menagerie', 'The World Is Your Dashboard', 'Homelab Minion Menagerie', 'Each server gets a client-side creature that follows you and acts out its health.', 'Five Proxmox nodes trail you through Gridania. One dozes, one sprints in circles at 100% CPU, one staggers under a smoking box at 95% disk, one plays dead. Click it and its tmux pane opens as a pet terminal.', 'Per-host health records over a new agent frame. Existing place_pet springs drive following. Ready fallback: ImGui billboard sprites on the same springs. Real version: client-side actors via ClientObjectManager or Brio IPC, with a BGCollision raycast for ground height and custom screen-space hit tests.', 'Client-spawned actors outside GPose are a known crash source and a grey area; they must despawn before zoning. Brio spawn outside GPose is uncertain. Many actors cost performance.', 'homelab folks, sysadmins, collectors', 1, 1, 0, 8, 'research', 'weeks', 3, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetheryte-uplink', 'The World Is Your Dashboard', 'Aetheryte Uplink', 'Aetherytes become status beacons for your hosts, and teleporting dissolves your terminals into aether that rebuilds on arrival.', 'Near an aetheryte, your hosts orbit the crystal as holographic rings with uptime and load, red if down. Cast Teleport and every panel streams into the loading screen, then rebuilds line by line at the destination, scrollback intact.', 'Shim adds FindNearest(Aetheryte) from IObjectTable. Lua reuses place_pet orbit math; worldview.nelua draws rings and halo. Host data from the shared probe/EVENT feed. Shim forwards Casting and BetweenAreas; worldview runs combat derez in reverse with a screen-space stream during loading and a line-reveal on arrival.', 'Halo is faked, not a real crystal tint; rings draw through geometry. Teleport detection is heuristic (Return, duty transitions). Needs a hide-hostnames option on stream.', 'homelab folks, sysadmins, anyone who teleports constantly', 1, 1, 0, 7, 'ready', 'days', 4, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('airship-departure-board', 'The World Is Your Dashboard', 'Airship Departure Board', 'CI/CD pipelines show as airship departures on a split-flap board at the landing or the FC workshop voyage console.', 'At the Limsa airship landing a split-flap board rattles to ''deploy/bazzite-sway: BOARDING'', then ''EN ROUTE'', then ''ARRIVED'' in green or ''LOST AT SEA'' in red with the failing step.', 'A world-pinned panel at per-territory coordinates running a `gh run list --json` TUI loop; flip transition per cell in core/render.nelua. Workshop console found by EventObj DataId via a small GetObject extension and pinned like a target anchor.', 'Thin novelty over a pinned dashboard. Repo names leak in public spots and on stream, so add redaction. Hardcoded coordinates break on zone changes.', 'developers, DevOps folks, FCs that hang out in the workshop', 1, 1, 0, 6, 'ready', 'days', 5, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('commit-constellations', 'The World Is Your Dashboard', 'Commit Constellations', 'On clear in-game nights, your git history hangs in the sky as constellations.', 'After dark, stars trace your commit graph: branches as trails, merges as clusters, today''s commits twinkling. Click one for its message and diffstat; double-click flies into `git show`. Day or clouds hide it.', 'Hidden agent session runs `git log --graph`. sky.lua lays nodes on a camera dome gated by GetEnvironment time, weather and rain. Stars drawn and hit-tested in worldview.nelua with the existing fly-in. Stretch: sky-only occlusion by sampling the depth buffer, as Pictomancy does.', 'Without depth occlusion stars draw over rooftops and the illusion breaks. Large graphs don''t read as constellations. Decorative and rarely looked at.', 'developers, open-source maintainers, screenshot hunters', 1, 1, 0, 6, 'stretch', 'weeks', 6, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('sit-down-to-work', 'Home Is Where the Shell Is', 'Sit Down to Work', 'Sit in any chair and your panels swing into a seated three-monitor arc while the camera settles into first person.', 'You /sit at your study desk. Wall panels spring into a curved arc at seated eye height, unfocused screens dim, the camera eases in. Stand up and everything springs back and your camera is restored.', 'Detect chair sit from ghostty.anim_state() Mode/ModeParam (or forward EmoteController id). Lua ''desk'' layout computes arc slots from seated position and heading and springs anchors there. Camera reuses the double-click Get/SetCameraState path, written once and restored once. Model M joins when it lands.', 'Tablet/typing pose overrides may knock you out of the chair, so disable them while seated. First-person near-plane clipping. Triggers in inns and public chairs unless limited to housing.', 'developers, roleplayers, cozy-workstation fans', 1, 1, 1, 8, 'ready', 'days', 7, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('drive-in-cinema', 'Home Is Where the Shell Is', 'Drive-In Cinema', 'A cinema-sized curved panel on your island or house wall, lit by the game''s sunset and rain, optionally broadcast read-only to opted-in friends.', 'At dusk you pin a huge screen over the island meadow and start asciinema. Its tint follows the sunset while rain streaks drift across. In the FC house, guests paste an invite code and watch the same live session at the same spot.', 'Solo works now: /term pin here plus lower pixels_per_yalm and a bigger curve radius; rain streaks from ghostty.env(); per-zone derez opt-out in worldview.nelua. Shared viewing (weeks, stretch): agent broadcast mode that streams output only and rejects DATA/OPEN/CLOSE, through a relay with per-invite keys, anchored by house ward/plot/room.', 'Truecolor text video repaints every cell and eats FPS; no kitty/sixel on the cell path. No depth, audio stays on the agent host. Agent token grants a shell today, so broadcast must be a separate read-only relay.', 'streamers, friend groups, FCs, event hosts, island decorators', 1, 1, 0, 8, 'ready', 'days', 8, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('furniture-anchors', 'Home Is Where the Shell Is', 'Mount to Furnishing', 'Pin terminals to real housing items, so a painting or bookshelf becomes a screen that moves with the furniture.', 'The painting in your apartment shows btop, the bookshelf `journalctl -f`. Drag the painting in the housing editor and the terminal slides along. It returns to the same frame on every visit.', 'Shim forwards HousingManager location (house/ward/plot/room) and IndoorTerritory furniture (item id, transform), as MakePlace and BDTH read. New ''furniture'' anchor in lua/world.lua matched by item id plus nearest transform, followed every frame, with per-item offset/size from a hand-made table. Replaces zone check with house-id check, since same-size houses share a territory id.', 'Panels show through walls and floors without depth; gate by room or height. Structs change with patches and load async. Identical adjacent items confuse matching. Frame fitting needs manual calibration.', 'housing decorators, homelab folks, roleplayers', 1, 1, 0, 7, 'stretch', 'days', 9, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('ghost-furniture-blueprints', 'Home Is Where the Shell Is', 'Blueprints with Ghost Furniture', 'Share a terminal installation as a paste-able blueprint, or import a MakePlace layout, that projects wireframe outlines where the furniture goes.', 'Paste a ''Garlemald Ops Center'' blueprint in your Mist apartment and scanline boxes appear where cabinets belong. Place a matching item and it turns solid, its terminal booting with a warm-up flicker after you fill in hostnames and approve each command.', 'Builds on furniture-anchors. Lua serializes anchors plus item id and relative transform to base64 and imports MakePlace JSON. Nelua draws projected wireframe boxes sized from a per-item table. Match detection by item id within tolerance; template form in views.nelua; warm-up reuses rez.', 'Must never write furniture positions: show a match indicator and let the player place. Shared commands are an RCE vector, so never auto-run and hash-pin blueprints. Only transfers between identical house sizes.', 'housing designers, homelab community, content creators', 1, 1, 0, 7, 'stretch', 'weeks', 10, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('homecoming-boot-sequence', 'Home Is Where the Shell Is', 'Homecoming Boot Sequence', 'Arriving home boots your installation screen by screen and marks what printed while you were away.', 'As the loading screen fades, wall screens light up one by one while sessions reattach, with away-time lines tinted amber until you look. Step into the ward and the room folds into a single orbiting pet.', 'Zone-gated anchors and agent replay already exist. Add on_zone_changed in Lua with staggered boot timers, per-session rez in worldview.nelua, an unread row mark in render.nelua set on sleep, and fold-out to one pet when no anchor matches. Per-house layouts need the housing location hook.', 'Amber marking fails for tmux and full-screen apps. Mostly presentation over existing persistence. Staggered boot needs a skip.', 'daily players with long jobs, developers, crafters', 1, 1, 0, 6, 'ready', 'days', 11, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('tablet-prop-shell', 'Body Language', 'The Tablet Prop Shows Your Shell', 'The tablet or book your character holds shows your live terminal on the game model itself.', 'Zoom in on the tomestone prop in your hands and htop updates on its screen, lit and depth-of-fielded by the game. GPose shots look like you''re on call from Eorzea.', 'Render the terminal to an offscreen texture (ITextureProvider draw-list wrap or D3D11 from Nelua), walk Character to weapon CharacterBase to Material texture, and swap its shader resource view each frame; a Penumbra mod gives a clean UV region. Cheap fallback: forward the hand bone world position and pin a small curved panel there.', 'Pointer-swapping game textures risks use-after-free crashes on zoning, redraws and Penumbra reloads. Shared texture shows your shell on every visible instance of that prop. Barely readable outside close-ups.', 'roleplayers, GPose photographers, streamers, sysadmins', 1, 1, 0, 9, 'research', 'weeks', 12, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('cast-bar-commands', 'Body Language', 'Commands Cast Like Spells', 'Long-running commands get an FFXIV cast bar and casting pose, and the exit code plays out as a spell effect.', 'Run `cargo build --release`: your character raises their weapon into a cast loop and ''Casting: cargo build'' fills against its usual runtime. Ctrl+C shatters the bar with ''Interrupted''. Exit 0 plays a chime and /victory; failure throws sparks and an optional /facepalm only you see.', 'Agent parses OSC 133 C/D in the PTY stream and sends CMD_START/CMD_END frames; OSC 9;4 and 777 via libghostty callbacks as fallback. New lua/cast.lua keeps EWMA durations, a minimum threshold, and picks timelines played through anim_play. Cast bar and particles drawn with ImGui above the projected player. Exit 130 = interrupt. Chime needs a UIGlobals.PlaySoundEffect forward; VFX optional.', 'Needs shell integration on every host, tmux passthrough, and remote hooks over ssh. animation.lua''s pose guard must yield during casts. Cast timelines vary by job and weapon state. Never touch ActionManager or the real _CastBar.', 'developers, raiders, streamers', 1, 1, 1, 8, 'ready', 'days', 13, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('wardrobe-by-hostname', 'Body Language', 'Wardrobe by Hostname', 'Glamourer IPC dresses you for the machine you''re on, so prod looks different from dev.', '`ssh prod-db-01` and you shimmer into a red hazard coat. Homelab tab: loungewear. A sudo prompt adds a crown until it closes. Exit and your glamour returns. Only you see it.', 'OSC 7 PWD_CHANGED and title give the host; forward on_host(id, host) to Lua. lua/wardrobe.lua maps globs to Glamourer designs for the focused session with ~1s debounce. Shim adds typed forwards for Glamourer apply/revert with a lock key. Sudo from a prompt regex on the cursor row.', 'Plain ssh without OSC 7 or titles gives nothing. Glamourer automation can fight the state; crash mid-apply leaves the outfit on. IPC signatures change, so pin the API version.', 'sysadmins, SREs, homelab folks, glamour enthusiasts', 1, 1, 0, 8, 'stretch', 'days', 14, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('emote-window-manager', 'Body Language', 'Emotes as a Window Manager', '/beckon calls a panel over, /point focuses one, /shoo minimizes it, and bound emotes run commands after confirmation.', '/beckon and your pet springs to your shoulder. /point across the plaza focuses the panel you''re facing. /pray is bound to `terraform plan`; a glowing sigil at your feet asks you to confirm.', 'anim_state() already returns TimelineIds[0]; lua/emotes.lua maps emote timeline ids to actions on rising edge. Point picks the smallest angle off facing. Bound commands go through sendtext.nelua. Sigil is a projected ImGui ellipse. EmoteController.EmoteId forward as backup.', 'Pose guard eats emotes within 0.1s, so whitelist them. Confirmation is mandatory and binds default read-only. Slower than hotkeys; mostly for fun.', 'nerds, roleplayers, streamers', 1, 1, 0, 7, 'ready', 'days', 15, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('flow-state-limit-break', 'Body Language', 'Flow-State Limit Break', 'Typing fast fills a client-side Limit Break gauge that fires a flourish at your peak.', 'A fast pace fills a three-segment LB gauge beside the dropdown with a rising aura. Hold 100 WPM for thirty seconds and your character plays a Limit Break just before `git push`. Stop and it drains.', 'Extend animation.lua typing energy with a rolling WPM window and three segments; ImGui gauge; payoff via anim_play of a job LB timeline the pose guard allows. Aura needs an actor VFX forward. Finger IK toward the Model M is dropped.', 'LB timelines are job-specific, some long and camera-bound. Rewards typing garbage into a shell. Aura VFX is stretch.', 'developers, streamers, speed typists', 1, 1, 0, 7, 'stretch', 'days', 16, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('gaze-and-presence', 'Body Language', 'Gaze and Presence', 'Your character turns to the focused panel, startles when a background terminal rings, and dozes after long idle.', 'Switch tabs and you turn to face the new panel. A pet behind you rings: you flinch, turn and it pulses. After ten idle minutes you nod off holding the tablet until a keystroke jolts you awake.', 'Body turn exists (rate-limited set_rotation); trigger on focus change. Bell already bound in ghostty.nelua; emit on_bell to Lua for a startle timeline, turn and backlight pulse. Doze is an idle timer in animation.lua. Head look-at is research and deferred.', 'Merge with the in-progress visual bell rather than building twice. Only rotate while stationary. Look-at conflicts with posing plugins.', 'roleplayers, developers leaving builds running', 1, 1, 0, 6, 'stretch', 'days', 17, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('job-codex-terminals', 'Body Language', 'Job Codex Terminals', 'The terminal''s physical form follows your job: codex pages for Scholar, a star globe for Astrologian, a wrist hologram for Machinist.', 'As Scholar your tmux windows are codex pages that flip when you switch windows. Swap to Astrologian and the same session becomes a turning sphere of panes. As Machinist it''s scanline hologram off your wrist.', 'Add ClassJob to GuObject. Lua style table per job selects frame, layout and pose. Nelua render variants: page-flip transition, spherical strip, rune/hologram overlays on existing scanline code. Page flip triggered by tmux window change. Bone anchoring is stretch; pet offset as fallback.', 'Per-job art and tuning is a large surface for a niche payoff; ship two or three. Bone positions vary by race and scale.', 'roleplayers, glamour enthusiasts, one-job mains, streamers', 1, 1, 0, 6, 'stretch', 'weeks', 18, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('moogle-mail', 'Mail Call', 'Moogle Mail', 'When a background job, ssh session or tmux alert finishes, a delivery moogle only you can see hands you the result as a letter.', 'Crafting in Ul''dah, a moogle flaps in holding an envelope: ''rsync nas -> offsite: complete, kupo!''. Open it and a parchment pane shows the log tail; a failure arrives singed with the stderr. Unread letters collect in a mailbag badge at your hip, and a local chat line ''Your retainer has returned: exit 0, 3m41s'' restores the tab on click.', 'Triggers: agent EXIT for detached sessions, OSC 9/777 and bell callbacks, plus an agent-side NOTIFY frame so sleeping sessions don''t miss completions. mail.lua queues letters (id, title, last N lines), holds them until out of combat and duty, and persists with layout. Parchment theme in render.nelua; letter opens as a pet via place_pet. v1 moogle: ImGui billboard from a game icon texture on pet springs; optional local IChatGui.Print with a link payload. v2: client-side moogle actor (weeks, research).', 'Client-side actors crash on zoning and must never spawn in duties or cutscenes. Sprite draws through walls. Needs shell integration or wrappers. Stderr on screen can leak secrets on stream. Share one pipeline with the visual bell and taskbar.', 'homelab folks, crafters and gatherers, sysadmins, roleplayers', 1, 1, 1, 8, 'stretch', 'days', 19, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('loot-roll-job-results', 'Mail Call', 'Loot-Roll Job Results', 'Jobs that finish mid-fight wait for combat to end, then drop at your feet as coffers you triage with Need, Greed or Pass.', '`term notify --after-combat make deploy` and you join a hunt train. The deploy finishes during an S-rank; a few seconds after combat a gold or red coffer drops with a chime. Need opens the log as a pet, Greed re-runs, Pass dismisses, all from the gamepad.', '`term notify` asks the agent via a control socket to OPEN a detached session; a PROTO_EVENT frame reports completion. Nelua queues while in_combat and releases after ~5s out. Lua ''drop'' anchor springs at your feet tinted by status. Need=ATTACH+make_pet, Greed=OPEN same argv, Pass=CLOSE via existing gesture code.', 'Combat flag flickers on trains; debounce. Skip bindings while the game''s NeedGreed addon is open. Greed re-running a deploy needs confirmation. ssh-launched jobs need the socket forwarded.', 'on-call sysadmins, developers with long CI, hunt train regulars', 1, 1, 0, 8, 'stretch', 'days', 20, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('cutscene-director', 'Mail Call', 'Cutscene Director', 'Long commands finish like a story beat: letterbox bars, a camera move to the panel, and a Talk-style box reading the result.', 'Out of combat and standing still, a 4-minute build finishes. Bars slide in, the camera flies to the panel, and a Talk box with the tab as speaker reads ''Build hath completed. 4m12s''. Failures glitch red with an error toast. Any input cancels.', 'Shares the OSC 133 CMD_END frame with cast-bar-commands. Shim forwards BoundByDuty/WatchingCutscene/OccupiedInEvent and IToastGui. lua/director.lua sequences bars, camera (existing fly-in SetCameraState), box and return. Talk box is ImGui with game ULD textures, not the real AddonTalk.', 'Unprompted camera moves are jarring; abort on any input or condition change. Needs shell integration. Command names show on stream.', 'developers, sysadmins, streamers', 1, 1, 0, 8, 'stretch', 'days', 21, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('pass-the-model-m', 'Party Up', 'Pass the Model M', 'Pair-program with a party member in one tmux session, and the floating Model M flies to whoever holds the keys.', '/term pair and a curved panel appears between you and your friend with a driver badge in the driver''s job color. /term pass and the Model M springs across the gap and clacks in time with their keystrokes. Hand the keys back before the duty pops.', 'Agent already fans output to multiple attached clients. Add scoped guest tokens (session ids, ro/rw), a per-session driver, and DRIVER/PASS frames over a tailnet. Lua ''between'' anchor at the midpoint of player and friend; Model M springs between them on driver events. Each client poses only its own character.', 'Guest tokens are a new security boundary on a TLS-less agent, so tailnet only; rw means arbitrary code as the host user. Seeing your friend''s pose locally is unproven. Depends on the in-progress Model M.', 'developers, homelab friends in the same FC, collab streamers', 1, 1, 0, 8, 'stretch', 'weeks', 22, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('over-the-shoulder-pets', 'Party Up', 'Over-the-Shoulder Pets', 'Friends who opt in make their orbiting pet terminal visible to you as a live read-only screen.', 'Target a friend who shared with you and a cyan outline marks their pet. Focus it and it resolves into their nethack run bobbing by their shoulder. An eye counter on their panel shows viewers; /term min darkens your view.', 'Read-only guest tokens scoped to one session plus a PAUSE frame on minimize; LIST already reports attached count. A second AgentClient per share with sessions flagged read-only. Invite carries name@world, matched against target/object table. Generalize the pet anchor to any entity_id.', 'Screens may show secrets; needs a clear broadcasting indicator. Skip or clear the 256 KiB replay for guests. Pet positions won''t line up exactly across clients.', 'streamers, roleplayers, FC mates, roguelike players', 1, 1, 0, 8, 'stretch', 'days', 23, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('static-war-room', 'Party Up', 'Static War Room', 'Your static or FC gets one read-only strat board pinned at the same arena wall or FC house spot on every member''s client.', 'Zone into savage and a curved panel fades in on the north wall for all eight of you. The lead scrolls the strat doc and every copy scrolls. On a wipe, ''pull 47, 6:12'' appends to a progression log. It derezzes in combat and returns sharp on the wipe; later the wall switches to the crafters'' market dashboard.', 'World anchors are identical across instances; share as a save_state snippet restored when zone matches (FC house needs HousingManager id). Members attach with read-only guest tokens to a separate broadcast agent; one PTY means scroll sync is free. Shim forwards IDutyState start/wipe/complete; only the lead writes pull number and time. Leader ping is an EVENT frame that turns pets and highlights rows.', 'Never parse combat events or show timelines, which would make it a trigger tool. Lead''s agent dropping kills everyone''s board. Discord screen share covers the basics. Needs opacity for sightlines.', 'raiders, static leads, FC leadership, progression streamers', 1, 1, 0, 8, 'stretch', 'days', 24, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('guest-terminal-scenes', 'Party Up', 'Allagan Terminal Scenes', 'RP hosts and venues run hackable in-world consoles backed by sandboxed scripts that invited players walk up to and use.', 'A GM pins a cyan Allagan-styled console in Castrum running a Lua text adventure. Invited players target it and type `override --sector 7`, their characters take the typing pose, everyone in the scene sees the same screen, and the GM replies live. A venue''s door kiosk runs a guestbook or drink menu the same way.', 'World anchor shared in the invite. Agent guest tokens with a forced command, like ssh ForceCommand: ATTACH only to the scene session, which runs in a container or restricted user. Client line-buffers and tags lines with name@world. Restricted session mode ignores OSC 52, notifications and hyperlinks. Theme palette plus a licensed fan font via the font atlas. Venue discovery by opt-in directory keyed on ward/plot is research.', 'Guests on a host is the core security problem: sandbox mandatory, rate caps, relay to hide IPs. Content sits outside SE moderation. Tiny audience, and non-plugin players see people typing at thin air.', 'roleplayers, RP venue hosts, event organizers, retro BBS nerds', 1, 1, 0, 8, 'stretch', 'days', 25, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('two-person-rule', 'Party Up', 'Two-Person Rule by Emote', 'Gate a dangerous command behind signed approvals from party members, with /thumbsup as the ritual.', '`ghostty-gate -- incus delete nas-old --force` shows PENDING, the diff and two empty slots. An FC mate reads it and /thumbsup; their slot fills with name and job icon. The second approval flashes the panel and the command runs as everyone watches.', 'Authority lives in the agent: held command, quorum policy, approver public keys, ed25519 verify via vendored monocypher over (hash, nonce, expiry), then forkpty. Frames PENDING/APPROVE/APPROVED. Approver''s plugin watches only its own timeline for thumbsup (or /term approve), signs and sends over a guest connection.', 'Keys inside the game process are readable by other plugins; pitch as oops-prevention, not security, with a hardware-key option. Enforce minimum view time on the diff. Real crypto in a hobby agent needs care.', 'sysadmins, SREs, homelab collectives', 1, 1, 0, 8, 'stretch', 'weeks', 26, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('paged-mid-pull', 'Party Up', 'Paged Mid-Pull', 'When your on-call healer gets paged, opted-in party members see a status line over them, so everyone knows why they went AFK.', 'Alertmanager fires and a red line appears over the healer: ''PAGED: disk 97% on nas01''. Their client rings and slides an incident terminal out of their pet slot. When it resolves the line turns green: ''back in 30s''.', 'Webhook receiver pushes a templated STATUS frame to the on-call''s agent. Party members hold status-only guest tokens. Map name@world to entity via IPartyList/object table and project an ImGui label above the head. Incident terminal reuses over-the-shoulder-pets.', 'Alert text leaks infra details; templated and redacted only. Ship as a mode of over-the-shoulder-pets and the bell, not a separate system. Hide labels in combat.', 'on-call engineers who raid, homelab statics', 1, 1, 0, 7, 'stretch', 'weeks', 27, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('linkpearl-bridge', 'Party Up', 'Linkpearl Bridge', 'Bridge your FC''s Matrix or IRC room into a linkshell-styled terminal that echoes lines only into your local chat log.', 'An FC mate on a train types ''healer for maps at 8?'' in Matrix; it appears locally as [Bridge] in its own color. You reply in weechat. Nothing reaches game chat.', 'weechat script emits OSC 777 on activity; surface on_notify to Lua (or an agent NOTIFY frame). Shim forwards IChatGui.Print, which is local-only. Lua filters, colors and rate-limits with a clearly non-game tag.', 'Low novelty. Chat logger plugins capture external messages. A tag resembling [LS1] invites replying in game chat. Throttle to avoid flooding mid-duty.', 'FC officers, friends split between game and Matrix/IRC', 0, 1, 0, 5, 'stretch', 'days', 28, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('wipe-rewind', 'Between Pulls', 'Wipe Rewind', 'After a wipe, a panel rises with your own last seconds and your static''s strat doc scrolled to the mechanic that killed you.', 'Party wipes; while running back a panel scans in showing the hits and debuffs you took from your own battle log, next to `strats.md` opened at that ability''s heading. When the countdown starts it sinks out with the derez.', 'Shim forwards IDutyState wipe/recommence and your own battle-log lines plus the countdown message. Nelua rings the last few seconds, sends them on wipe, and drives rez up, then down on countdown. `wipe recap` maps ability names to headings and opens `less +/''^## ability''`.', 'Post-wipe review of your own data only; no live callouts. Avoid parsing ACT/IINACT network logs. Ability-to-heading maps are hand-maintained per fight; text depends on client language.', 'progression raiders, statics, raid leads with strat docs in git', 1, 1, 0, 8, 'stretch', 'days', 29, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('queue-pop-eject', 'Between Pulls', 'Queue Pop Eject', 'When the Duty Finder pops, whatever terminal owns your screen lets go, and an opt-in hook lets your desk react.', 'Thirty minutes into full-screen vim, the roulette pops. The panel peels off the camera into pet orbit, input returns to the game, and the tab counts down 45 seconds in red. On the host, a hook pauses music and renices your build.', 'Shim forwards IClientState.CfPop duty id via gu_event. Nelua clears world_full_id and stops capturing keyboard. Lua on_duty_pop picks pet or minimize and sets a countdown title cleared on WaitingForDutyFinder/BoundByDuty. Client-to-agent EVENT frame fork/execs an opt-in hook with only DUTY_ID in env.', 'Focus not released means you can''t press Commence; test hardest. CfPop may miss some queue types. Never auto-commit, never type into the PTY.', 'roulette grinders, developers who queue while working, streamers', 1, 1, 0, 7, 'stretch', 'days', 30, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('crafting-solver', 'Between Pulls', 'Crafting Solver Over the Anvil', 'Open a recipe and a terminal above your workstation runs a real solver on your stats and prints paste-ready macros.', 'Pick a new Master recipe and a panel streams a raphael-rs search with a progress bar using your craftsmanship, control and CP. The macro splits into 15-line chunks; tap A to copy chunk 1 and paste it yourself.', 'Shim forwards recipe id from AgentRecipeNote, stats from PlayerState, job level, triggered on RecipeNote PostRefresh. Agent control socket feeds `craft watch` running raphael-cli. OSC 52 handled in core via igSetClipboardText, so any CLI can copy. Panel anchored above player while PreparingToCraft.', 'Stop at the clipboard; executing macros is automation. Food and potion buffs must be active. Big solves eat minutes and GBs on the host.', 'crafters gearing for expert recipes', 1, 1, 0, 7, 'stretch', 'days', 31, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('eorzea-cron', 'Between Pulls', 'Eorzea Cron', 'A crontab on Eorzea time and weather that rings your pet terminal for timed nodes and weather spawns.', '`ecron ''zone=Ruby Sea weather=Thunder ET>=08:00'' notify ''Unspoiled node up''`. When the window opens, your pet panel rings. `ecron list` shows the next real-world time for every rule.', 'Host-side: ET = unix*3600/175, weather forecast from WeatherRate tables in a Lumina/Teamcraft dump, run by a systemd user timer. Notification writes BEL into the pet session; bell already bound. Optional amber pre-pulse via EVENT frame and a tint term in lighting().', 'WeatherRate tables change with patches. Island Sanctuary and Occult Crescent don''t follow simple rules. GatherBuddy already has alarms; the draw is shell scripting.', 'gatherers, mount and minion hunters, cron nerds', 0, 1, 0, 6, 'ready', 'days', 32, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('market-board-hover', 'Between Pulls', 'Hover-to-Shell Market Board', 'Hovered items stream into your shell, so a Universalis CLI draws cross-world price history beside the retainer bell.', 'Open your retainer sell list and a panel beside the bell runs `mb watch`. Hover each item and it redraws a braille sparkline, cheapest listings across your DC and sales velocity. You still set every price by hand.', 'Shim forwards IGameGui.HoveredItemChanged and home DC via gu_event; Nelua debounces ~150ms and relays PROTO_EVENT. `term events --kind hover` feeds a shell script calling Universalis. Panel shown while OccupiedSummoningBell.', 'Not every row raises a tooltip. Universalis is crowd-sourced and rate-limited. Existing plugins already show prices; the draw is your own tooling. Never write prices back.', 'market board flippers, crafters, gil-makers', 1, 1, 0, 6, 'stretch', 'days', 33, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('party-finder-fzf', 'Between Pulls', 'fzf the Party Finder', 'Party Finder listings stream into your shell as JSON lines for jq and fzf.', 'Open the Party Finder and `pf | fzf` fuzzy-searches every description for ''practice'' minus ''clear pf''. Pick one and its row is highlighted if visible, or its page and recruiter are printed.', 'Shim forwards IPartyFinderGui.ReceiveListing fields as JSON via gu_event; `pf` streams from the agent socket. Highlight is a read-only ImGui rect over LookingForGroup row nodes; no driving the addon.', 'Only pages the game fetched arrive. Strip control characters from player text to avoid escape injection. Keep recruiter names in memory only. Row layout is fragile.', 'raiders hunting practice parties, jq reflexes', 0, 1, 0, 6, 'stretch', 'days', 34, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('xhb-shell-slots', 'Between Pulls', 'Live Cross Hotbar Shell Slots', 'Hotbar slots bound to shell jobs show live progress rings, so a Steam Deck player can watch a build without opening a terminal.', 'Cross hotbar set 8 holds build, ci and backup. A ring fills as `term slot ci progress 0.6` updates; a failure turns the slot red and shakes it. Hold the slot to peek the log tail as a pet, release to send it back.', 'Shim forwards _ActionCross/_ActionBar slot rects plus RaptureHotbarModule and macro text. Nelua maps `/term focus <name>` slots (needs named sessions) and draws rings on the foreground list. `term slot` arrives as PROTO_EVENT. Hold detection from GamepadDown plus active set.', 'HUD layouts, WXHB and scale plugins break slot rects. Macro fires on press before hold. Niche for the effort.', 'Steam Deck and controller players, couch homelabbers', 0, 1, 0, 6, 'stretch', 'days', 35, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('echo-replays', 'Showtime', 'Echo Replays', 'Replay old terminal sessions as ghost holograms in the exact spot they happened, framed like the game''s Echo visions.', 'Walk back to where you fixed the homelab at 3am and type /term echo. The screen flashes white and a translucent cyan panel rezzes in, replaying the session at real speed. Triggers scrub; /term echo loop 30 loops a stretch for stream.', 'Agent records asciicast-style timestamped output and resizes plus territory and coordinates; REC_LIST/REC_OPEN/REC_CHUNK frames. Replay transport feeds Session:feed on a clock, reusing TermView and rendering. Keyframes every ~5s via libghostty formatter for seeking. Flash, rez-in and ghost tint reuse existing effects.', 'Recordings keep every token and hostname printed: retention limits, per-profile opt-out, playback redaction. Disk growth. Keyframes may not restore every mode exactly.', 'roleplayers, streamers, developers', 1, 1, 1, 8, 'ready', 'days', 36, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetherial-visualizer', 'Showtime', 'Aetherial Visualizer', 'Audio from a terminal''s player makes panel backlights and pet terminals pulse to the beat.', 'Start ncmpcpp and panel backlights pulse on the bass, pets kick on their springs, and bars mode raises columns under the panel.', 'Agent matches PipeWire nodes to the PTY process tree, captures with pw-record, runs a windowed FFT, and sends 8-16 bands as a BANDS frame at 30-60Hz. Lua modulates backlight and adds pet spring impulses; bars are extra projected quads.', 'Audio over ssh plays remotely and can''t be captured. Crowds see nothing unless synced. Needs intensity cap and photosensitivity toggle. Flatpak and pulse-compat matching is fragile.', 'streamers, roleplayers, venue and club hosts', 1, 1, 0, 7, 'stretch', 'weeks', 37, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('stream-redaction', 'Showtime', 'Stream Redaction Mode', 'Streamer mode seals password prompts and secret-looking text on every panel before it''s drawn, with an optional Eorzean-script skin for looks.', 'Panels keep layout, color and motion, but password prompts, API tokens and IPs become sealed crystal tiles. Panels marked public stay readable. The Eorzean-script skin is style only, since fans can read it.', 'Agent checks tcgetattr after reads and sends SECRET_INPUT when ECHO is off with ICANON. lua/redact.lua regexes dirty rows (ghp_, AKIA, JWT, IPs, *_TOKEN=, key headers); render.nelua draws crystal quads over returned ranges on every surface including the first frame after wake. Cipher skin is a second font handle. Public flag persisted with layout.', 'ECHO signal fails inside tmux and ssh, leaving only regex; a missed pattern leaks. Masking must never lag a frame. No hold-to-peek, since OBS captures it. Fan font licensing.', 'streamers, sysadmins, homelab folks', 1, 1, 0, 6, 'ready', 'days', 38, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('credits-roll', 'Showtime', 'Duty Complete Credits Roll', 'Clearing a duty rolls Final Fantasy-style credits across your pet terminals, written from your session.', 'After the clear, the camera orbits your character while pets scroll ''Directed by <alias>'', ''Wipes: 14'', ''Commands run between pulls: 212'', ''Longest command: cargo build, 6m03s'', with party members as job icons. Any input skips.', 'Shim forwards IDutyState and IPartyList ClassJob ids; icons from ITextureProvider. lua/credits.lua builds text from Enter counts and CMD_END durations and feeds generated VT into a local session. Orbit via SetCameraState spring, gated on WatchingCutscene.', 'Must not cover the loot window or exit prompt. Default alias must not leak hostname. Duration stats need OSC 133.', 'raiders, streamers, developers', 1, 1, 0, 6, 'ready', 'days', 39, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('obs-scene-conductor', 'Showtime', 'OBS Scene Conductor', 'Duty and panel events switch OBS scenes, and stream triggers fire whitelisted cosmetic effects in game.', 'Starting a duty switches to your Raid scene and ducks terminal audio; flying a panel full screen switches to Code. Channel-point redeems via Streamer.bot fire a derez burst or spin your pets, and a camera swoop only out of combat.', 'Shim forwards IDutyState and TerritoryChanged; core sends EVENT frames to the agent. A small sidecar speaks obs-websocket v5 and relays inbound events as EFFECT frames. lua/effects.lua maps them to whitelisted calls gated on InCombat and BoundByDuty.', 'Viewer camera control is risky if a gate fails. The agent holds another credential and any network exposure widens a shell-granting service. Frame-locked browser overlays are dropped.', 'streamers', 0, 1, 0, 6, 'stretch', 'weeks', 40, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('gpose-terminal-studio', 'Showtime', 'GPose Terminal Studio', 'Terminals stay in group pose as frozen props you can scroll back, move, tilt or attach to a character''s hand.', 'In GPose each panel freezes instead of vanishing. Scroll to an earlier moment, drag or tilt it, or attach it to an actor''s hand bone so your character holds the real screen.', 'Set DisableGposeUiHide; confirm draw callbacks and ViewProjection follow the GPose camera. Freeze via Session:sleep. Drag/rotate gizmo on world_hit/world_unproject. Hand attach via a GetBone shim forward reading hkaPose and a Lua ''bone'' anchor.', 'ImGui overlays never get game DoF or lighting and cover other actors. The game''s screenshot likely excludes Dalamud''s layer. Bone math breaks on ClientStructs changes.', 'GPose photographers, roleplayers, streamers', 1, 1, 0, 6, 'research', 'weeks', 41, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('aetheryte-ssh-network', 'Nerd Power Tools', 'Aetheryte Network for SSH', 'Your ~/.ssh/config becomes a teleport menu, and connecting casts a client-side teleport that lands a shell beside you.', 'ctrl+t opens an Aetheryte-style host list grouped by ProxyJump chain, RTT as cost, unknown hosts unattuned. Pick one: your character casts, the current panel derezzes, and a pet lands at the remote prompt. Expand a host to attach its tmux sessions as shards.', 'New Nelua primitive ghostty.run(argv, cb) capture session plus ghostty.command(text). Agent-host helper prints TSV from `ssh -G`, `ssh-keygen -F` and a TCP connect time; tmux shards via ControlMaster only on expand. Lua menu in core/ui.nelua table widget; anim_play cast timeline, derez, open `ssh -t host` and pin as pet. No shim changes.', 'Can''t hijack the real Teleport keybind. Probes can trip 2FA, fail2ban or slow DNS, so TCP connect only. Cast timeline must not lock movement. Real teleport VFX is research.', 'sysadmins, homelab folks, anyone with too many SSH hosts', 1, 1, 1, 8, 'ready', 'days', 42, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('deploy-raid-pull', 'Nerd Power Tools', 'Deploy as a Raid Pull', 'CI jobs show as party frames, and a production deploy needs a charged Limit Break hold before Enter goes through.', 'The GitHub Actions run shows as party frames: HP is steps done, cast bar the current step, enrage the timeout, debuff icons on failures that open `gh run view --log-failed`. Type `terraform apply` and Enter becomes a three-segment LB gauge you hold to fill. Green runs play victory.', 'Capture session polls `gh run list/view --json` every ~10s to TSV; frames drawn with new ui.* progress widgets. ghostty.input_line(session) reads cursor-row cells with SEMANTIC_CONTENT==INPUT (OSC 133). keymap.lua swallows Enter on guarded patterns until the hold fills, then sends \r. Victory via anim_play, skipped while BoundByDuty.', 'A speed bump, not a safety control: needs OSC 133 and is bypassed from any other terminal. Swallowing Enter needs a visible reason and Esc to cancel. gh rate limits.', 'developers, DevOps engineers, raiders', 0, 1, 0, 8, 'stretch', 'days', 43, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('parse-your-shell', 'Nerd Power Tools', 'Parse Your Shell', 'An ACT-style meter ranks your session''s commands by time and colors each like an FFLogs parse.', 'Your slowest `nix build` is grey, a quick test run purple, your best `make check` gold. Failed commands get death markers. Click a row to jump to that prompt''s output; copy a text summary to paste wherever you like.', 'Agent parses OSC 133 with libghostty''s standalone OSC parser and timestamps an EVENT frame delivered even to detached sessions. Lua keeps per-command history and percentiles and draws colored bars. Jump scans rows for SEMANTIC_PROMPT. Summary via SetClipboardText only.', 'Needs OSC 133 through tmux and ssh. Scrollback lost on sleep/restart. Percentiles mean little with few runs. No automated chat sends.', 'raiders who are developers, performance nerds', 0, 1, 0, 7, 'stretch', 'days', 44, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('git-status-buffs', 'Nerd Power Tools', 'Git Status as Buffs and Debuffs', 'Each pet terminal gets a mob-style nameplate with its branch and a buff row for repo state.', 'Your pet reads ''feature/observatory <bazzite-sway>'' with the last exit code as its level. Below: a stack count of dirty files, ahead/behind arrows, a crystal per stash, and a pulsing Doom icon during a merge conflict. Click Doom to type `git status`.', 'precmd hook runs `git status --porcelain=v2 --branch` with a timeout and emits a private OSC user var. Wire UNKNOWN_SEQUENCE in session.nelua to Lua on_uservar. worldview projects the nameplate above each pet via a world.nameplate(id) hook; click uses /term type.', 'Slow git in big repos adds prompt lag. Check whether OSC 1337 SetUserVar reaches the callback; else use an unused OSC number. Overlapping nameplates, stale state while asleep.', 'developers who live in git', 1, 1, 0, 6, 'ready', 'days', 45, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('grep-the-world', 'Terminal Craft', '/grep the World', 'One scrollback search across every terminal you own, with hit counts floating over panels and ''next'' flying the camera to the match.', '/term find OOMKilled and every panel with a match gets a ''3'' badge and a soft pulse, including the pet at your shoulder. Next turns the camera to the panel, scrolls and highlights the line. On controller, the d-pad steps between shell prompts.', 'libghostty-vt ships vt/search.h with incremental feed/tick across screens and scrollback. One GhosttySearch per Session, a few ticks per frame. Highlight as selection, scroll via scroll_delta, badges projected in draw_world, counts in the Umbra popup for minimized tabs. Camera reuses fly-in easing; prompt stepping via SEMANTIC_PROMPT.', 'Sleeping panels only retain the 256 KiB replay ring; search agent-side or say so plainly. Byte-exact matching, no regex. Prompt stepping needs shell integration.', 'sysadmins, homelab folks, on-call engineers who raid', 1, 1, 1, 8, 'ready', 'days', 46, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('folding-screen-splits', 'Terminal Craft', 'Folding Screen Splits', 'Splitting a world terminal hinges it into a folding screen of panes you can angle, fold shut and walk around.', 'ctrl+shift+\ creases a world panel down the middle: vim on the left leaf, tests on the right. Split again for a triptych around your desk with the focused leaf lit. Drag a hinge to open flat or fold a leaf shut while its process keeps running.', 'Each leaf is its own Session; add group id and leaf index to layout persistence. Lua computes leaf placement from the group anchor with hinge yaw animated by spring(). No new projection math. Hinge drag is a new grip mode calling policy_world_hinge. Folded leaves sleep via sleep_unseen. /term split and fold commands.', 'Overlapping leaves need depth-sorted picking. Long-folded panes lose older scrollback on wake. Resizing a leaf must rebalance neighbours.', 'tmux addicts, sysadmins, housing decorators, roleplayers', 1, 1, 1, 8, 'ready', 'weeks', 47, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('kitty-graphics-tapestries', 'Terminal Craft', 'Kitty Graphics Tapestries', 'Kitty graphics protocol images render on 3D panels, so live dashboards and pictures hang in the world like paintings.', '`watch -n30 ''curl grafana/render/... | kitten icat''` on a panel pinned to your house wall and a live Grafana graph hangs there as a curved tapestry, tinted by time and weather. It returns with a scanline wipe when the panel wakes.', 'libghostty-vt already implements kitty graphics placements. Decode PNG with vendored stb_image or Zig. Shim forwards CreateTexture/ReleaseTexture via ITextureProvider.CreateFromRaw, cached by image id. Draw placements as tessellated quads so world_transform_vertices curves and tints them; plain AddImage in 2D. No sixel.', 'Images vanish past the replay ring on sleep or restart unless re-sent or cached agent-side. Cap texture memory in-process; create on the render thread and free on unload or crash.', 'homelab folks, streamers, venue decorators', 1, 1, 0, 8, 'stretch', 'weeks', 48, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('item-links', 'Terminal Craft', 'Item Links in stdout', 'OSC 8 links with an ffxiv:// scheme turn CLI output into item tooltips, map flags and chat-ready item links.', 'A crafter script prints ''Grade 8 Tincture of Strength x3 @ 4,200g''. Hover for an icon-and-stats tooltip, ctrl+click to put a real item link in your chat input to send yourself, or click coordinates to drop a map flag.', 'Mouse to cell to GhosttyGridRef, then ghostty_grid_ref_hyperlink_uri, sharing mouse-selection plumbing. Lua parses item/map/quest URIs into typed actions. Shim forwards Lumina Item lookup and icon, OpenMapWithMapLink, and a chat-input item link insert. ImGui tooltip first; native tooltip later.', 'Output is untrusted: typed actions only, click required, never free text into chat. Chat-input insertion depends on unstable ClientStructs internals.', 'crafters, gatherers, market goblins, CLI tool authors', 0, 1, 0, 8, 'stretch', 'weeks', 49, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('legible-at-distance', 'Terminal Craft', 'Legible at 40 Yalms', 'Distance LOD for world panels: full text up close, block minimap rows mid-range, a one-line nameplate far away.', 'htop on a Limsa pillar is crisp up close. Walk away and lines become colored blocks shaped like the text; further, the panel collapses to a nameplate: ''build passed 3m12s''. Distant panels also get cheaper.', 'draw_world already has projected corners; divide by rows for on-screen cell height and pick glyphs, run blocks (reuse the merged background-run loop), or nameplate from title, last row or OSC 9;4 progress. Lua owns thresholds with hysteresis. Font mip handles at 20/40/80px chosen in PushWorldFont. MSDF is research.', 'No ligatures: per-cell AddText, no shaper. Big font atlases grow fast. LOD pop needs cross-fade.', 'developers, sysadmins, screenshotters, streamers', 1, 1, 0, 7, 'stretch', 'days', 50, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('soul-crystal-themes', 'Terminal Craft', 'Soul Crystal Themes', 'Terminal palettes re-derive live from your job, HUD theme and chat colors, and the prompt can show the real job icon.', 'Swap from WHM to DRK and every terminal crossfades to a palette from the job color, diff additions in FC-chat green, errors in Tell pink. Your starship prompt shows the job as the game icon.', 'Set GHOSTTY_TERMINAL_OPT_COLOR_PALETTE with a per-frame lerp; lua/theme.lua builds 16 colors with a contrast clamp while app OSC overrides still win. Shim forwards ClassJob, ClassJobChanged and IGameConfig HUD/chat colors. Job icon drawn as a texture at a placeholder codepoint; prompt queries job via custom OSC.', 'SeIconChar shares the PUA with Nerd Font powerline glyphs and ImWchar is 16-bit, hence textures. Job colors have poor contrast without clamping. Config option names need checking.', 'developers, job-swapping raiders, ricers, streamers', 0, 1, 0, 7, 'stretch', 'days', 51, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('terminal-perf-meter', 'Terminal Craft', 'Parse Your Terminals', 'A /term perf meter colors each terminal''s frame cost like a DPS parse, and a governor tightens budgets inside duties.', '/term perf shows draw ms, vertices and PTY bytes/sec per tab: grey at 0.3ms, pink for the cmatrix tab burning 4ms. Entering a duty throttles unwatched panels (''budget 1.5ms, 2 throttled''); GPose lifts all caps.', 'QueryPerformanceCounter around draw_terminal and world_transform_vertices, vertex deltas, byte counters per session. Governor caches flat panel geometry and on throttled frames skips render_state_update and render_termview, re-running only the transform. Shim forwards BoundByDuty, IsGPosing and local chat print.', 'Stale geometry cache after resize or font change draws garbage. Combat derez already cuts much of the duty cost. Chat notice should be opt-in.', 'raiders, performance nerds, streamers, low-end laptops', 0, 1, 0, 6, 'ready', 'days', 52, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('accessibility-inheritance', 'Terminal Craft', 'Inherits Your Accessibility Settings', 'The terminal follows the game''s color-blindness filter, supports accessible fonts per tab, and can speak matching output lines.', 'With deuteranopia filter on, red/green diffs become blue/orange. Tabs can use Atkinson Hyperlegible or OpenDyslexic. A tab marked spoken reads lines matching ERROR aloud, so a failing deploy is audible mid-pull.', 'CVD-safe palette preset chosen from a forwarded IGameConfig color-filter option. Per-profile font handles via AddFontFromFile. Agent strips escapes, regex-matches lines and sends a small frame; speech via host-side piper/espeak, SAPI or TextToTalk IPC as options.', 'No global high-contrast mode to inherit; offer a manual AAA palette. SAPI under Wine is poor, so prefer host TTS. Rate-limit speech so it never talks over callouts.', 'colorblind, low-vision and dyslexic players, raiders who can''t look away', 0, 1, 0, 6, 'stretch', 'days', 53, 1, 0)
INSERT INTO ideas (id, category, title, pitch, experience, how, risks, audience, in_world, tos_safe, top_pick, wow, feasibility, effort, sort_order, added_version, retired) VALUES ('kana-on-the-curve', 'Terminal Craft', 'Kana on the Curve', 'IME composition text renders inline at the cursor, even on curved world panels, with a game-styled candidate list.', 'A Japanese player types into nvim on an apartment panel: composition text appears underlined at the cursor, bending with the panel, and kanji candidates pop out beside it. Same in the dropdown, ssh and tmux.', 'Committed text and wide cells already work. Shim hooks WM_IME_COMPOSITION/ImmGetCompositionString (or reflects into Dalamud) to forward preedit and cursor. render.nelua draws the underlined overlay in the same draw range so world_transform_vertices curves it. Candidate frame is ImGui; merge a CJK font subset.', 'CJK at 40px bloats the atlas; ImWchar is 16-bit so no astral characters. IME through Wine/Proton on Linux is unreliable. WndProc hooks can conflict with Dalamud''s IME.', 'JP/CN/KR players, multilingual developers, roleplayers', 1, 1, 0, 6, 'research', 'weeks', 54, 1, 0)
